('g3_2_sci_u4_L01_basic#6','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',2,'mc','auto','그림 속 친구의 볼이 분홍색으로 붉어진 것을 보고 짐작할 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u4-X02']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"mc","stem":"그림 속 친구의 볼이 분홍색으로 붉어진 것을 보고 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"열이 나는 것 같다","correct":true},{"t":"콧물을 흘린다","mis":"SC3-2-u4-X02"},{"t":"잠이 온다","mis":"SC3-2-u4-X02"},{"t":"배가 고프다","mis":"SC3-2-u4-X02"}],"explanation":["볼이 붉어졌어요.","얼굴이 달아올랐어요.","열이 나는 것 같아요."]}'::jsonb),
('g3_2_sci_u4_L01_basic#7','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C2',2,'mc','auto','친구들의 경험에서 감기와 관련 없는 경험은 무엇인가요?',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C2","difficulty":2,"kind":"mc","stem":"친구들의 경험에서 감기와 관련 없는 경험은 무엇인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"SC3-2-u4-X04"},{"t":"㉡","mis":"SC3-2-u4-X04"},{"t":"㉣","mis":"SC3-2-u4-X04"}],"explanation":["하나씩 읽어요.","다친 일을 찾아요.","㉢이에요."],"asset":{"type":"passage","lines":["㉠ 동생에게서 감기가 옮아 가족이 모두 아팠어요.","㉡ 환절기에 감기에 걸려 콧물이 났어요.","㉢ 뛰다가 넘어져서 무릎을 다쳤어요.","㉣ 친구와 놀다가 감기가 옮았어요."],"title":"친구들의 경험"}}'::jsonb),
('g3_2_sci_u4_L01_basic#8','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',2,'mc','auto','먼저 다 칠한 친구가 해야 할 알맞은 행동은 무엇인가요?',ARRAY['SC3-2-u4-X03']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"mc","stem":"먼저 다 칠한 친구가 해야 할 알맞은 행동은 무엇인가요?","options":[{"t":"정답을 말하지 않고 다른 친구가 스스로 찾도록 기다린다","correct":true},{"t":"큰 소리로 정답을 외친다","mis":"SC3-2-u4-X03"},{"t":"친구 그림을 대신 칠해 준다","mis":"SC3-2-u4-X03"},{"t":"빨리 칠했다고 자랑한다","mis":"SC3-2-u4-X03"}],"explanation":["스스로 찾게 해요.","조용히 기다려요.","정답을 말하지 않아요."]}'::jsonb),
('g3_2_sci_u4_L01_basic#9','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C1',2,'ox','auto','사인펜으로 칠하면 지우개로 쉽게 지울 수 있으니 숫자를 확인하지 않아도 돼요.',ARRAY['SC3-2-u4-X01']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"ox","stem":"사인펜으로 칠하면 지우개로 쉽게 지울 수 있으니 숫자를 확인하지 않아도 돼요.","answer":"X","reason_options":[{"t":"사인펜은 한 번 칠하면 고치기 어려워 숫자를 잘 확인하고 칠해야 하기 때문에","correct":true},{"t":"틀리면 언제든 쉽게 지울 수 있기 때문에","mis":"SC3-2-u4-X01"}],"mis":"SC3-2-u4-X01","explanation":["사인펜을 떠올려요.","고치기 어려워요.","그래서 X예요."]}'::jsonb),
('g3_2_sci_u4_L01_basic#10','sci',3,2,'u4','L01','g3_2_sci_u4_L01_basic','lesson_basic','SC3-2-u4-C2',3,'mc','auto','친구들의 경험을 「다른 사람에게서 옮은 경험인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":10,"concept":"SC3-2-u4-C2","difficulty":3,"kind":"mc","stem":"친구들의 경험을 「다른 사람에게서 옮은 경험인가?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉣","correct":true},{"t":"㉠, ㉡","mis":"SC3-2-u4-X04"},{"t":"㉡, ㉢","mis":"SC3-2-u4-X04"},{"t":"㉢, ㉣","mis":"SC3-2-u4-X04"}],"explanation":["옮았다는 말을 찾아요.","동생, 친구예요.","㉠, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 동생에게서 감기가 옮아 가족이 모두 아팠어요.","㉡ 환절기에 감기에 걸려 콧물이 났어요.","㉢ 뛰다가 넘어져서 무릎을 다쳤어요.","㉣ 친구와 놀다가 감기가 옮았어요."],"title":"친구들의 경험"}}'::jsonb),
('g3_2_sci_u4_L01_challenge#1','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',2,'match','auto','숫자와 칠할 색깔을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u4-C1","difficulty":2,"kind":"match","stem":"숫자와 칠할 색깔을 알맞게 이으세요.","pairs":[{"l":"숫자 1","r":"검은색"},{"l":"숫자 3","r":"분홍색"},{"l":"숫자 4","r":"하늘색"}],"mis":"SC3-2-u4-X01","explanation":["짝을 떠올려요.","4는 코 밑 줄이에요.","1-검은색, 3-분홍색, 4-하늘색이에요."],"asset":{"type":"passage","lines":["1 검은색 — 머리카락과 눈, 코, 입이 나타나요.","2 주황색 — 입 둘레가 나타나요.","3 분홍색 — 양쪽 볼이 나타나요.","4 하늘색 — 코 밑으로 줄이 나타나요.","5 살구색 — 얼굴이 나타나요.","6 노란색 — 그림의 바탕이 나타나요."],"title":"색칠 놀이 숫자와 색깔"}}'::jsonb),
('g3_2_sci_u4_L01_challenge#2','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C2',2,'mc','auto','친구가 놀이터에 나오지 않은 까닭을 완성된 그림으로 짐작한 것은 무엇인가요?',ARRAY['SC3-2-u4-X02','SC3-2-u4-X04']::text[],false,'{"seq":2,"concept":"SC3-2-u4-C2","difficulty":2,"kind":"mc","stem":"친구가 놀이터에 나오지 않은 까닭을 완성된 그림으로 짐작한 것은 무엇인가요?","options":[{"t":"감기에 걸려 몸이 아팠다","correct":true},{"t":"이사를 갔다","mis":"SC3-2-u4-X02"},{"t":"숙제를 하고 있었다","mis":"SC3-2-u4-X02"},{"t":"약속을 잊어버렸다","mis":"SC3-2-u4-X04"}],"explanation":["그림 속 모습을 떠올려요.","콧물이 나고 열이 나요.","감기에 걸렸어요."]}'::jsonb),
('g3_2_sci_u4_L01_challenge#3','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',3,'error','auto','색칠 놀이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u4-X03','SC3-2-u4-X01','SC3-2-u4-X02']::text[],false,'{"seq":3,"concept":"SC3-2-u4-C1","difficulty":3,"kind":"error","stem":"색칠 놀이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「가장 빨리 칠한 사람이 이기는 놀이야.」","correct":true,"mis_target":"SC3-2-u4-X03"},{"t":"친구 가 — 「숫자를 확인하고 정해진 색으로 칠하자.」","mis":"SC3-2-u4-X01"},{"t":"친구 다 — 「다 칠하면 그림 속 친구의 상황을 짐작해 보자.」","mis":"SC3-2-u4-X02"}],"explanation":["놀이의 목적을 떠올려요.","빠르기가 중요할까요?","친구 나가 잘못 말했어요."]}'::jsonb),
('g3_2_sci_u4_L01_challenge#4','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',3,'mc','auto','그림 속 단서와 짐작한 내용을 바르게 이은 것은 무엇인가요?',ARRAY['SC3-2-u4-X02']::text[],false,'{"seq":4,"concept":"SC3-2-u4-C1","difficulty":3,"kind":"mc","stem":"그림 속 단서와 짐작한 내용을 바르게 이은 것은 무엇인가요?","options":[{"t":"붉은 볼 — 열 · 코 밑 하늘색 줄 — 콧물","correct":true},{"t":"붉은 볼 — 콧물 · 코 밑 하늘색 줄 — 열","mis":"SC3-2-u4-X02"},{"t":"붉은 볼 — 잠 · 코 밑 하늘색 줄 — 웃음","mis":"SC3-2-u4-X02"},{"t":"두 단서 모두 아무 뜻이 없다","mis":"SC3-2-u4-X02"}],"explanation":["단서를 하나씩 봐요.","볼은 달아올랐어요.","볼-열, 줄-콧물이에요."]}'::jsonb),
('g3_2_sci_u4_L01_challenge#5','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C2',3,'mc','auto','「감기와 관련된 경험인가?」로 나누었을 때 ✕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":5,"concept":"SC3-2-u4-C2","difficulty":3,"kind":"mc","stem":"「감기와 관련된 경험인가?」로 나누었을 때 ✕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"넘어져 무릎을 다친 일, 약속을 잊어 놀이터에 못 간 일","correct":true},{"t":"감기가 심해져 병원에 간 일, 넘어져 무릎을 다친 일","mis":"SC3-2-u4-X04"},{"t":"친구에게서 감기가 옮은 일, 약속을 잊은 일","mis":"SC3-2-u4-X04"},{"t":"환절기에 콧물이 난 일, 감기가 심해져 병원에 간 일","mis":"SC3-2-u4-X04"}],"explanation":["감기와 상관없는 것을 찾아요.","다친 일과 잊은 일이에요.","두 가지를 묶어요."]}'::jsonb),
('g3_2_sci_u4_L01_challenge#6','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C2',3,'ox','auto','감기에 걸린 경험뿐 아니라 감기가 옮은 경험도 감기와 관련된 경험이에요.',ARRAY['SC3-2-u4-X04']::text[],false,'{"seq":6,"concept":"SC3-2-u4-C2","difficulty":3,"kind":"ox","stem":"감기에 걸린 경험뿐 아니라 감기가 옮은 경험도 감기와 관련된 경험이에요.","answer":"O","reason_options":[{"t":"걸린 일도 옮은 일도 모두 감기와 관련 있기 때문에","correct":true},{"t":"내가 아팠던 일만 감기 경험이기 때문에","mis":"SC3-2-u4-X04"}],"mis":"SC3-2-u4-X04","explanation":["두 경험을 견줘요.","둘 다 감기예요.","그래서 O예요."]}'::jsonb),
('g3_2_sci_u4_L01_challenge#7','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',3,'mc','auto','색칠 놀이 숫자와 색깔에서 친구의 얼굴과 그림의 바탕을 칠하는 숫자를 차례대로 쓴 것은 무엇인가요?',ARRAY['SC3-2-u4-X01']::text[],false,'{"seq":7,"concept":"SC3-2-u4-C1","difficulty":3,"kind":"mc","stem":"색칠 놀이 숫자와 색깔에서 친구의 얼굴과 그림의 바탕을 칠하는 숫자를 차례대로 쓴 것은 무엇인가요?","options":[{"t":"5, 6","correct":true},{"t":"6, 5","mis":"SC3-2-u4-X01"},{"t":"1, 2","mis":"SC3-2-u4-X01"},{"t":"3, 4","mis":"SC3-2-u4-X01"}],"explanation":["얼굴과 바탕을 찾아요.","살구색과 노란색이에요.","5, 6이에요."],"asset":{"type":"passage","lines":["1 검은색 — 머리카락과 눈, 코, 입이 나타나요.","2 주황색 — 입 둘레가 나타나요.","3 분홍색 — 양쪽 볼이 나타나요.","4 하늘색 — 코 밑으로 줄이 나타나요.","5 살구색 — 얼굴이 나타나요.","6 노란색 — 그림의 바탕이 나타나요."],"title":"색칠 놀이 숫자와 색깔"}}'::jsonb),
('g3_2_sci_u4_L01_challenge#8','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C2',4,'mc','auto','친구가 「나는 감기 경험이 없어서 이야기할 게 없어.」라고 했어요. 가장 알맞게 도와준 말은 무엇인가요?',ARRAY['SC3-2-u4-X04','SC3-2-u4-X03']::text[],false,'{"seq":8,"concept":"SC3-2-u4-C2","difficulty":4,"kind":"mc","stem":"친구가 「나는 감기 경험이 없어서 이야기할 게 없어.」라고 했어요. 가장 알맞게 도와준 말은 무엇인가요?","options":[{"t":"「가족이나 친구가 감기에 걸렸던 일, 감기가 옮았던 일도 이야기할 수 있어.」","correct":true},{"t":"「넘어져 다친 일을 감기 경험이라고 말하면 돼.」","mis":"SC3-2-u4-X04"},{"t":"「감기는 옮지 않으니 아무 경험이나 말해.」","mis":"SC3-2-u4-X04"},{"t":"「경험은 말하지 말고 그림만 빨리 칠하자.」","mis":"SC3-2-u4-X03"}],"explanation":["감기와 관련된 일을 떠올려요.","옮은 일도 돼요.","첫 번째가 알맞아요."]}'::jsonb),
('g3_2_sci_u4_L01_challenge#9','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',4,'mc','auto','친구 그림의 코 밑이 하늘색이 아니라 노란색으로 칠해졌어요. 그 까닭과 다음에 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u4-X01','SC3-2-u4-X02','SC3-2-u4-X03']::text[],false,'{"seq":9,"concept":"SC3-2-u4-C1","difficulty":4,"kind":"mc","stem":"친구 그림의 코 밑이 하늘색이 아니라 노란색으로 칠해졌어요. 그 까닭과 다음에 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"숫자 4 대신 6의 색으로 칠했으니, 다음에는 칸의 숫자를 확인하고 칠한다","correct":true},{"t":"노란색이 더 예쁘니 그대로 두면 된다","mis":"SC3-2-u4-X01"},{"t":"콧물이 노란색이라서 맞게 칠한 것이다","mis":"SC3-2-u4-X02"},{"t":"먼저 끝낸 친구가 정답을 알려 주면 된다","mis":"SC3-2-u4-X03"}],"explanation":["4는 무슨 색일까요?","노란색은 6이에요.","숫자를 확인해요."],"asset":{"type":"passage","lines":["1 검은색 — 머리카락과 눈, 코, 입이 나타나요.","2 주황색 — 입 둘레가 나타나요.","3 분홍색 — 양쪽 볼이 나타나요.","4 하늘색 — 코 밑으로 줄이 나타나요.","5 살구색 — 얼굴이 나타나요.","6 노란색 — 그림의 바탕이 나타나요."],"title":"색칠 놀이 숫자와 색깔"}}'::jsonb),
('g3_2_sci_u4_L01_challenge#10','sci',3,2,'u4','L01','g3_2_sci_u4_L01_challenge','lesson_challenge','SC3-2-u4-C1',4,'essay','teacher','색칠 놀이로 완성한 그림에서 찾은 단서 두 가지를 쓰고, 친구가 놀이터에 나오지 못한 까닭을 짐작해 쓰세요. 그리고 색칠 놀이에서 지킬 약속을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u4-C1","difficulty":4,"kind":"essay","stem":"색칠 놀이로 완성한 그림에서 찾은 단서 두 가지를 쓰고, 친구가 놀이터에 나오지 못한 까닭을 짐작해 쓰세요. 그리고 색칠 놀이에서 지킬 약속을 한 가지 쓰세요.","answer_guide":{"answer":"예: 양쪽 볼이 분홍색으로 붉어져 열이 나는 것 같고, 코 밑에 하늘색 줄이 있어 콧물을 흘리는 것 같다. 그래서 친구는 감기에 걸려 몸이 아파 놀이터에 나오지 못했을 것이다. 먼저 다 칠해도 정답을 말하지 않고 친구가 스스로 찾도록 기다린다.","scoring_points":["그림 속 단서 두 가지를 썼는가","단서를 바탕으로 친구의 상황을 짐작했는가","색칠 놀이 약속을 썼는가"]},"explanation":["그림을 떠올려요.","단서를 써요.","약속을 써요."]}'::jsonb),
