('g3_2_sci_u4_review_d#22','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C17',3,'mc','auto','손 씻기를 「가장 간단하면서도 효과적인 예방 방법」이라고 하는 까닭은 무엇인가요?',ARRAY['SC3-2-u4-X37','SC3-2-u4-X38','SC3-2-u4-X27']::text[],false,'{"seq":22,"concept":"SC3-2-u4-C17","difficulty":3,"kind":"mc","stem":"손 씻기를 「가장 간단하면서도 효과적인 예방 방법」이라고 하는 까닭은 무엇인가요?","options":[{"t":"누구나 쉽게 할 수 있고, 올바르게 씻기만 해도 많은 감염병을 예방할 수 있어서","correct":true},{"t":"세계 손 씻기의 날에만 하면 돼서","mis":"SC3-2-u4-X37"},{"t":"손이 깨끗해 보이면 안 해도 돼서","mis":"SC3-2-u4-X38"},{"t":"물만 묻혀도 돼서","mis":"SC3-2-u4-X27"}],"explanation":["간단하고 효과적이에요.","많은 감염병을 막아요.","첫 번째예요."]}'::jsonb),
('g3_2_sci_u4_review_d#23','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C10',4,'essay','teacher','다솜반 일지 ⑤의 ㉠, ㉡, ㉣ 가운데 두 가지를 골라 무엇을 통해 감염될 수 있는지 쓰고, 각각 감염병을 막는 습관으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC3-2-u4-C10","difficulty":4,"kind":"essay","stem":"다솜반 일지 ⑤의 ㉠, ㉡, ㉣ 가운데 두 가지를 골라 무엇을 통해 감염될 수 있는지 쓰고, 각각 감염병을 막는 습관으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: ㉠은 손을 씻지 않은 채 간식을 먹어 손을 통해 감염될 수 있으니, 간식을 먹기 전에 비누로 흐르는 물에 30초 이상 손을 씻는다. ㉣은 확인하지 않은 물을 마셔 오염된 물을 통해 감염될 수 있으니, 깨끗한 물인지 확인하고 마신다.","scoring_points":["한 습관의 감염 과정을 썼는가","다른 습관의 감염 과정을 썼는가","두 습관을 막는 습관으로 바르게 바꾸었는가"]},"explanation":["두 가지를 골라요.","감염 과정을 써요.","습관을 바꿔요."],"asset":{"type":"passage","lines":["㉠ 운동장에서 놀고 손을 씻지 않은 채 간식을 먹었다.","㉡ 열이 나는데도 사람이 많은 놀이공원에 갔다.","㉢ 기침이 나서 옷소매로 입과 코를 가렸다.","㉣ 여행 중에 확인하지 않은 물을 마셨다."],"title":"다솜반 일지 ⑤ 생활 습관 돌아보기"}}'::jsonb),
('g3_2_sci_u4_review_d#24','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C18',4,'mc','auto','다솜반 일지 ⑧의 친구 가가 다음에 손을 씻을 때 가장 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u4-X40','SC3-2-u4-X27','SC3-2-u4-X39']::text[],false,'{"seq":24,"concept":"SC3-2-u4-C18","difficulty":4,"kind":"mc","stem":"다솜반 일지 ⑧의 친구 가가 다음에 손을 씻을 때 가장 알맞은 방법은 무엇인가요?","options":[{"t":"비누를 쓰고 흐르는 물에 30초 이상, 손바닥부터 손톱 밑까지 6단계를 모두 한다","correct":true},{"t":"손톱 밑만 오래 문지르고 나머지는 뺀다","mis":"SC3-2-u4-X40"},{"t":"물만 묻히고 손톱 밑을 한 번 본다","mis":"SC3-2-u4-X27"},{"t":"6단계를 거꾸로 손톱 밑부터 손바닥 하나만 한다","mis":"SC3-2-u4-X39"}],"explanation":["빠뜨린 단계를 넣어요.","여섯 단계 모두예요.","첫 번째예요."],"asset":{"type":"passage","lines":["10월 15일에 손 씻기 6단계를 함께 해 보았다.","친구 가는 손톱 밑 문지르기를 빠뜨렸다.","반 다짐 — 「이날만이 아니라 매일 올바르게 씻자.」"],"title":"다솜반 일지 ⑧ 세계 손 씻기의 날"}}'::jsonb),
('g3_2_sci_u4_review_d#25','sci',3,2,'u4','','g3_2_sci_u4_review_d','unit_review','SC3-2-u4-C11',4,'essay','teacher','「감염병과 건강한 생활」 단원에서 배운 감염병의 뜻, 감염병의 위험성, 생활 습관과 감염병 유행, 감염병 예방 수칙 가운데 세 가지를 골라 각각 한 문장으로 설명하고, 내가 생활 속에서 실천할 예방 수칙을 구체적으로 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u4-C11","difficulty":4,"kind":"essay","stem":"「감염병과 건강한 생활」 단원에서 배운 감염병의 뜻, 감염병의 위험성, 생활 습관과 감염병 유행, 감염병 예방 수칙 가운데 세 가지를 골라 각각 한 문장으로 설명하고, 내가 생활 속에서 실천할 예방 수칙을 구체적으로 한 가지 쓰세요.","answer_guide":{"answer":"예: 감염병은 병원체에 감염되어 생기는 질병이다. 감염병은 누구나 걸릴 수 있고 다른 사람에게 옮아 많은 사람에게 퍼질 수 있다. 생활 습관은 감염병 유행에 영향을 미친다. 나는 기침할 때 옷소매로 입과 코를 가리겠다.","scoring_points":["세 가지를 골랐는가","세 가지를 배운 내용에 맞게 설명했는가","실천할 예방 수칙을 구체적으로 썼는가"]},"explanation":["배운 것을 떠올려요.","세 가지를 골라요.","실천할 수칙을 써요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO3-2-u1-C1','soc',3,2,'u1',1,'사회의 변화와 원인 — 사회의 모습은 끊임없이 변해 사라지는 모습, 새로 생기는 모습, 다른 모습으로 바뀌는 모습이 있음 · 원인: 사람 수의 변화, 평균 수명의 증가, 사람들의 생각 변화, 과학 기술의 발달, 다른 나라와의 교류(실제로는 여러 원인이 얽힘) · 옛 학교: 학생은 많고 교실은 부족해 오전반·오후반, 점심 도시락, 이름은 국민학교, 교실 난로 → 오늘날 급식·초등학교 · 학생이 줄어 문을 닫는 학교, 노인 복지관, 청소 로봇, 세계 음식 가게',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],1),
('SO3-2-u1-C2','soc',3,2,'u1',2,'저출산으로 달라진 생활 — 저출산은 태어나는 아이의 수가 줄어 출산율이 감소하는 현상 · 그래프(우리나라에서 연도별 태어나는 아이의 수, 가로 연도·세로 만 명): 1970년 101만 → 1980년 86만 → 1990년 65만 → 2000년 64만 → 2010년 47만 → 2020년 27만, 점점 줄어듦 · 까닭: 결혼하지 않거나 아이를 낳아 기르는 데 부담을 느끼는 사람이 많아짐 · 영향: 학생 수와 일할 수 있는 사람 수가 줄어듦 · 노력: 아이를 낳고 키우는 데 필요한 돈과 물품 지원, 안전하고 쾌적한 보육 시설, 부모가 일을 쉴 수 있는 제도',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],2),
('SO3-2-u1-C3','soc',3,2,'u1',3,'고령화로 달라진 생활 — 65세 이상을 노인이라 함 · 의학 기술이 발달하고 깨끗한 환경에서 생활하게 되어 오래 살게 됨 · 고령화는 전체 사람 수에서 노인의 수가 차지하는 비율이 높아지는 현상(비율 = 일정한 양을 기준으로 어떤 양이 차지하는 정도) · 100명 마을이라면 노인이 1980년 4명 정도 → 2020년 16명 정도 → 2050년(예상) 40명 정도 · 달라진 모습: 노인 복지관, 노인 전문 병원·요양 시설, 노인 배움 프로그램, 일하는 노인 · 노력: 복지 제도, 알맞은 일자리, 노인을 위한 물건 개발, 노후 생활 준비 지원',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],3),
('SO3-2-u1-C4','soc',3,2,'u1',4,'지능정보화로 달라진 생활 — 정보 통신 기술은 전화·컴퓨터 같은 기기로 정보를 주고받는 기술, 인공지능은 사람처럼 정보를 익히고 처리해 여러 상황에 적용하는 컴퓨터 시스템 · 지능정보화는 인공지능을 활용한 다양한 기술이 사회 전반에 폭넓은 영향을 미치는 현상 · 편리해진 점: 배달 로봇, 맞춤 교육, 목소리 인식 기기, 안전 운전 도움 · 문제: 사이버 범죄, 거짓 정보 확산, 인터넷·스마트폰 과의존, 일자리 감소 · 노력: 사이버 범죄 감시, 올바른 사용 습관 지원, 인공지능 활용 능력 교육, 직업 환경 대응 교육 · 장점은 누리고 단점은 보완 · 개인 정보를 함부로 공유하지 않기, 인터넷 정보를 비판 없이 믿지 않기, 정해진 규칙에 따라 사용하기',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],4),
('SO3-2-u1-C5','soc',3,2,'u1',5,'세계화로 달라진 생활 — 세계화는 세계 여러 나라가 다양한 분야에서 교류하며 전 세계가 하나로 연결되는 현상 · 모습: 다른 나라 음식·과일·영화, 함께하는 행사, 세종 학당(한국어와 한국에 관한 내용을 가르침), 한류(대한민국과 관련 있는 것들이 다른 나라에서 인기를 얻는 현상) · 물건은 다른 나라에서 들어오기도 하고(초콜릿·포도·청바지) 우리나라 회사가 다른 나라에 공장을 짓기도 함(라면·초코과자) — 서로 주고받으며 연결 · 문제: 각 나라의 전통적인 생활 양식 약화, 감염병이 빠르게 퍼짐 · 태도: 다른 나라의 생활 양식을 장단점을 따져 받아들이기, 우리 생활 양식 소중히 여기기, 세계 여러 나라의 문제를 함께 해결하려는 자세',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],5),
('SO3-2-u1-C6','soc',3,2,'u1',6,'사회 변화로 달라진 생활 정리 — 저출산·고령화·지능정보화·세계화의 뜻과 달라진 모습, 문제, 대응 방안을 차례로 정리(주제 → 모습 → 문제 → 대응 방안) · 복지 제도·정보 통신 기술·출산율 같은 낱말 · 카드 뉴스·포스터로 나타내기 · 사회 변화로 나타난 문제를 해결하려면 우리 모두 관심을 갖고 함께 노력해야 함',ARRAY['[4사03-01] 사회 변화(저출산·고령화·지능정보화·세계화 등)로 나타난 일상생활의 모습을 탐색하고, 그 특징을 분석한다(차시 머리 주석 기준)']::text[],6),
('SO3-2-u1-C7','soc',3,2,'u1',7,'문화의 뜻과 특징 — 문화는 한 사회의 사람들이 지닌 공통의 생활 양식(사람들이 함께 생활하며 만들어지고 오래 전해져 내려오기도 함) · 배고파서 먹기·졸려서 자기처럼 태어날 때부터 하는 행동은 문화가 아님 · 의식주(옷·음식·집), 말과 글, 음악, 미술, 종교, 규범(마땅히 따르고 지켜야 할 생각이나 행동의 기준) 등 · 지역의 환경에 따라 생활 양식이 다양함(추운 곳 털옷, 햇볕 강한 곳 긴 옷) · 각 사회의 문화는 비슷한 점도 있고 다른 점도 있음(새 학년 시작 달, 인사 방법, 공부하는 과목) · 축제는 한 사회의 문화를 잘 드러냄',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],7),
('SO3-2-u1-C8','soc',3,2,'u1',8,'우리 사회의 다양한 문화 — 이주민은 다른 지역에서 옮겨 와 사는 사람 · 외국인 이주민 수가 늘어남(111만 명 → 213만 명), 세계화의 영향으로 직장·공부·결혼 등 여러 목적 · 1인 가구는 가족과 같이 살지 않고 혼자 사는 경우, 결혼에 관한 생각 변화·혼자 사는 노인 증가로 늘어남 · 반려동물은 사람과 더불어 살며 친밀감과 안정감을 주는 동물, 반려동물 놀이터·공원·행사가 생김 · 한 동네에 여러 문화가 함께 있음',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],8),
('SO3-2-u1-C9','soc',3,2,'u1',9,'다양한 문화 확산의 영향 — 좋은 점과 문제가 함께 나타남 · 외국인 이주민: 세계 여러 나라 문화를 경험할 기회가 늘어남 / 종교·언어·피부색이 다르다는 까닭으로 부당한 대우, 편견과 차별 · 1인 가구: 작은 가전제품·적은 양 포장 상품·장보기 등을 대신하는 활동 / 외로움·불안함, 도움을 청할 사람이 없음 · 반려동물: 마음의 안정, 수의사·훈련사·미용사 같은 직업 / 소음·배설물·냄새로 이웃 간 갈등(소음이 가장 많음), 버려지는 동물 · 편견은 공정하지 못하고 한쪽으로 치우친 생각, 차별은 편견을 가지고 다르게 대우하는 것',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],9),
('SO3-2-u1-C10','soc',3,2,'u1',10,'문제를 해결하려는 노력과 존중하는 태도 — 만화 영화 속 미나는 피부색을 이상하게 여길까 봐 모자를 씀 · 사회의 노력: 한국 생활에 필요한 정보를 다양한 언어로 제공, 국가 인권 위원회(편견과 차별을 막는 제도·기관), 1인 가구 프로그램과 안전 지원, 반려견 산책 때 입마개·목줄, 유니버설 디자인(누구나 쓰기 쉽게 디자인) · 바람직한 태도: 편견을 갖지 않고 차별하지 않기, 다른 문화의 사람들이 겪는 어려움에 관심, 서로 다름을 인정하고 존중 — 바람직하지 못한 태도(무시·경계, 이상하게 여기기, 비난)가 하나라도 있으면 안 됨',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],10),
('SO3-2-u1-C11','soc',3,2,'u1',11,'다양한 문화에 대한 이해와 존중 정리 — 문화·이주민·1인 가구·반려동물·편견과 차별에 관한 설명이 알맞은지 가리기 · 축제 초대장 만들기: 주제 정하기 → 프로그램 계획 → 내용과 장소 정하기 → 초청하는 글 쓰기 · 이주민·1인 가구·반려동물 축제 프로그램 · 다양한 문화를 대할 때는 서로 다름을 인정하고 존중',ARRAY['[4사03-02] 우리 사회에 나타나는 다양한 문화의 모습을 살펴보고, 문화의 다양성을 존중하는 태도를 기른다(차시 머리 주석 기준)']::text[],11)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO3-2-u1-X01','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'사회의 모습은 한번 정해지면 변하지 않는다고, 또는 사라지거나 생기는 것 가운데 한쪽만 있다고 여긴다','사라지고 · 생기고 · 바뀌어요'),
('SO3-2-u1-X02','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'사회가 변하는 원인을 한 가지로만 보거나, 사회와 관계없는 일(해가 뜨는 것 등)을 원인으로 여긴다','사람 수 · 수명 · 생각 · 기술 · 교류'),
('SO3-2-u1-X03','soc',3,'u1',ARRAY['SO3-2-u1-C1']::text[],'옛날과 오늘날의 학교·생활 모습을 바꾸어 안다(옛날에 급식을 먹었다고 여기는 등)','옛날 도시락 · 오늘날 급식'),
('SO3-2-u1-X04','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산의 뜻을 거꾸로 안다(태어나는 아이의 수가 늘어나는 현상으로 여기는 등)','태어나는 아이가 줄어요'),
('SO3-2-u1-X05','soc',3,'u1',ARRAY['SO3-2-u1-C2','SO3-2-u1-C3']::text[],'그래프·그림 자료를 잘못 읽는다(가로·세로·단위를 헷갈리거나, 거의 같으면 변하지 않았다고 여기는 등)','제목 · 가로 · 세로 · 단위'),
('SO3-2-u1-X06','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산이 계속될 때 달라지는 모습을 거꾸로 안다(학생 수나 일할 사람이 늘어난다고 여기는 등)','학생 수 · 일할 사람이 줄어요'),
('SO3-2-u1-X07','soc',3,'u1',ARRAY['SO3-2-u1-C2']::text[],'저출산 문제를 해결하려는 노력을 잘못 안다(학교 문을 닫는 것을 노력으로 여기는 등)','지원 · 보육 시설 · 쉴 수 있는 제도'),
('SO3-2-u1-X08','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'고령화를 노인의 수만 늘어나는 것으로, 또는 노인의 비율이 낮아지는 것으로 여긴다','전체에서 노인이 차지하는 비율이 높아져요'),
('SO3-2-u1-X09','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'사람들이 오래 살게 된 까닭을 잘못 안다','의학 기술 · 깨끗한 환경'),
('SO3-2-u1-X10','soc',3,'u1',ARRAY['SO3-2-u1-C3']::text[],'고령화로 달라진 모습이나 대비하려는 노력을 거꾸로 안다(노인을 위한 시설이 줄어든다고 여기는 등)','시설 · 프로그램 · 일자리가 늘어요'),
('SO3-2-u1-X11','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'정보 통신 기술·인공지능·지능정보화의 뜻을 서로 바꾸어 안다','주고받는 기술 · 생각하는 컴퓨터 · 넓은 영향'),
('SO3-2-u1-X12','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'지능정보화로 편리해진 점과 생겨난 문제를 바꾸어 짝짓는다','누려요 · 보완해요'),
('SO3-2-u1-X13','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'지능정보화를 한쪽으로만 본다(편리하니 문제는 걱정 없다, 또는 문제가 있으니 아예 쓰지 말자)','장점은 누리고 단점은 보완해요'),
('SO3-2-u1-X14','soc',3,'u1',ARRAY['SO3-2-u1-C4']::text[],'인터넷·태블릿 컴퓨터를 쓸 때 지킬 점을 잘못 안다(개인 정보를 올리거나 정보를 그대로 믿는 등)','개인 정보 · 비판하며 · 규칙대로'),
('SO3-2-u1-X15','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화의 뜻을 잘못 안다(다른 나라 물건을 사기만 하는 것, 한 나라하고만 교류하는 것으로 여기는 등)','여러 나라가 하나로 연결돼요'),
('SO3-2-u1-X16','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화로 다른 나라에서 들어오기만 한다고 여겨, 우리나라가 다른 나라에 영향을 주는 모습(한류·공장)을 놓친다','들어오고 나가요'),
('SO3-2-u1-X17','soc',3,'u1',ARRAY['SO3-2-u1-C5']::text[],'세계화로 생긴 문제나 대응 태도를 잘못 안다(다른 나라 생활 양식을 무조건 따르거나 모두 거부하는 등)','장단점을 따져 받아들여요'),
('SO3-2-u1-X18','soc',3,'u1',ARRAY['SO3-2-u1-C6','SO3-2-u1-C2','SO3-2-u1-C3','SO3-2-u1-C4','SO3-2-u1-C5']::text[],'저출산·고령화·지능정보화·세계화의 뜻이나 모습을 서로 바꾸어 짝짓는다','아이 · 노인 · 인공지능 · 여러 나라'),
('SO3-2-u1-X19','soc',3,'u1',ARRAY['SO3-2-u1-C6']::text[],'사회 변화로 생긴 문제는 나라만 해결하면 되고 우리와는 관계없다고 여긴다','모두 관심을 갖고 함께 노력해요'),
('SO3-2-u1-X20','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'배고파서 먹기·졸려서 자기처럼 태어날 때부터 하는 행동을 문화라고 여긴다','함께 만든 공통의 생활 양식'),
('SO3-2-u1-X21','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'문화를 의식주만으로 좁게 보거나, 의식주·규범 같은 낱말의 뜻을 바꾸어 안다','말과 글 · 음악 · 종교 · 규범도 문화'),
('SO3-2-u1-X22','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'다른 사회의 문화는 잘못되었다고, 또는 모든 사회의 문화가 똑같다고 여겨 비슷한 점과 다른 점을 놓친다','비슷한 점도 있고 다른 점도 있어요'),
('SO3-2-u1-X23','soc',3,'u1',ARRAY['SO3-2-u1-C7']::text[],'지역의 환경에 따라 생활 양식이 달라진다는 점을 놓친다','추운 곳 · 더운 곳 · 햇볕 강한 곳'),
('SO3-2-u1-X24','soc',3,'u1',ARRAY['SO3-2-u1-C8']::text[],'이주민·1인 가구·반려동물의 뜻을 서로 바꾸어 안다','옮겨 와 사는 사람 · 혼자 사는 집 · 더불어 사는 동물'),
('SO3-2-u1-X25','soc',3,'u1',ARRAY['SO3-2-u1-C8']::text[],'우리 사회의 다양한 문화가 늘어난 까닭이나 변화를 거꾸로 안다(1인 가구가 줄어든다고 여기는 등)','늘어나고 있어요 · 까닭이 있어요'),
('SO3-2-u1-X26','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'다양한 문화가 확산된 영향을 한쪽으로만 본다(좋은 점만 있다, 또는 문제가 있는 문화는 없애야 한다)','밝은 면과 그늘 면이 함께'),
('SO3-2-u1-X27','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'편견과 차별의 뜻을 바꾸어 안다(편견을 행동으로, 차별을 생각으로 여기는 등)','편견은 생각 · 차별은 행동'),
('SO3-2-u1-X28','soc',3,'u1',ARRAY['SO3-2-u1-C9']::text[],'다양한 문화가 확산된 영향을 사람들(이주민·1인 가구·반려동물과 함께 사는 사람)과 잘못 짝짓는다','누구와 관계있는 모습일까요'),
('SO3-2-u1-X29','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'문제를 해결하려는 사회의 노력을 잘못 알거나, 노력이 필요 없다고 여긴다','다양한 언어 · 인권 위원회 · 유니버설 디자인'),
('SO3-2-u1-X30','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'다른 문화를 무시하거나 이상하게 여기는 바람직하지 못한 태도를 괜찮다고 여긴다','하나라도 있으면 탑이 기울어요'),
('SO3-2-u1-X31','soc',3,'u1',ARRAY['SO3-2-u1-C10']::text[],'다양한 문화를 대할 때 우리 문화만 소중히 여기고 다른 문화는 낮추어 본다','서로 다름을 인정하고 존중해요'),
('SO3-2-u1-X32','soc',3,'u1',ARRAY['SO3-2-u1-C11']::text[],'축제 초대장 만들기 차례나 축제 프로그램을 잘못 짝짓는다','주제 → 프로그램 → 내용·장소 → 초청 글')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g3_2_soc_u1_L01_basic#1','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'mc','auto','사회의 모습에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"mc","stem":"사회의 모습에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"사회의 모습은 끊임없이 변해요","correct":true},{"t":"사회의 모습은 언제나 똑같아요","mis":"SO3-2-u1-X01"},{"t":"사회의 모습은 사라지기만 해요","mis":"SO3-2-u1-X01"},{"t":"사회의 모습은 새로 생기기만 해요","mis":"SO3-2-u1-X01"}],"explanation":["옛날과 오늘을 견줘요.","모습이 달라졌어요.","끊임없이 변해요."]}'::jsonb),
('g3_2_soc_u1_L01_basic#2','soc',3,2,'u1','L01','g3_2_soc_u1_L01_basic','lesson_basic','SO3-2-u1-C1',1,'sa','auto','옛날에는 초등학교를 「○○학교」라고 불렀어요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u1-C1","difficulty":1,"kind":"sa","stem":"옛날에는 초등학교를 「○○학교」라고 불렀어요. ○○에 알맞은 두 글자를 쓰세요.","answer":["국민"],"explanation":["지금 이름과 달라요.","◯민학교예요.","국민학교예요."],"mis":"SO3-2-u1-X03"}'::jsonb),
