('g3_2_soc_u1_review_d#22','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C9',3,'mc','auto','반려동물로 이웃 간에 갈등이 생긴 까닭 가운데 가장 많은 것과 그다음으로 많은 것을 차례대로 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u1-X05']::text[],false,'{"seq":22,"concept":"SO3-2-u1-C9","difficulty":3,"kind":"mc","stem":"반려동물로 이웃 간에 갈등이 생긴 까닭 가운데 가장 많은 것과 그다음으로 많은 것을 차례대로 짝지은 것은 무엇인가요?","options":[{"t":"소음 — 배설물","correct":true},{"t":"냄새 — 소음","mis":"SO3-2-u1-X05"},{"t":"배설물 — 소음","mis":"SO3-2-u1-X05"},{"t":"물림 — 냄새","mis":"SO3-2-u1-X05"}],"explanation":["소음이 첫째예요.","그다음을 떠올려요.","배설물이에요."]}'::jsonb),
('g3_2_soc_u1_review_d#23','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C1',4,'mc','auto','「사회 변화와 다양한 문화」 단원을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u1-X01','SO3-2-u1-X19','SO3-2-u1-X26']::text[],false,'{"seq":23,"concept":"SO3-2-u1-C1","difficulty":4,"kind":"mc","stem":"「사회 변화와 다양한 문화」 단원을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"사회는 여러 원인으로 변하며 생활 모습이 달라지고, 다양한 문화가 늘어나는 사회에서는 서로 다름을 인정하고 존중해야 해요","correct":true},{"t":"사회는 변하지 않고 문화도 하나뿐이에요","mis":"SO3-2-u1-X01"},{"t":"사회 변화로 생긴 문제는 나라만 해결해요","mis":"SO3-2-u1-X19"},{"t":"다양한 문화가 퍼지면 좋은 점만 생겨요","mis":"SO3-2-u1-X26"}],"explanation":["사회 변화예요.","다양한 문화예요.","존중해요."]}'::jsonb),
('g3_2_soc_u1_review_d#24','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C5',4,'essay','teacher','신문 ④에서 세계화의 모습 두 가지를 찾아 쓰고, 세계화에 대응하는 바람직한 태도를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u1-C5","difficulty":4,"kind":"essay","stem":"신문 ④에서 세계화의 모습 두 가지를 찾아 쓰고, 세계화에 대응하는 바람직한 태도를 쓰세요.","answer_guide":{"answer":"예: 동네 시장에 다른 나라 과일 가게가 생겼고, 동네 회사가 다른 나라에 공장을 지었어요. 다른 나라의 생활 양식을 무조건 따르지 않고 장단점을 따져 받아들이며, 우리 생활 양식도 소중히 여겨야 해요.","scoring_points":["세계화의 모습 두 가지를 찾았는가","들어오고 나가는 모습이 드러났는가","바람직한 태도를 썼는가"]},"explanation":["들어온 것이 있어요.","나간 것도 있어요.","태도를 써요."],"asset":{"type":"passage","lines":["동네 시장에 다른 나라 과일을 파는 가게가 생겼다.","우리 동네의 한 회사는 다른 나라에 공장을 지었다.","다른 나라 친구에게 한국어를 가르쳐 주는 형도 있다."],"title":"신문 ④ — 세계와 이어진 우리 동네"}}'::jsonb),
('g3_2_soc_u1_review_d#25','soc',3,2,'u1','','g3_2_soc_u1_review_d','unit_review','SO3-2-u1-C11',4,'essay','teacher','신문 ⑧처럼 우리 반이 다양한 문화를 알리는 축제를 연다면 주제, 프로그램, 장소를 정하고 초청하는 글을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u1-C11","difficulty":4,"kind":"essay","stem":"신문 ⑧처럼 우리 반이 다양한 문화를 알리는 축제를 연다면 주제, 프로그램, 장소를 정하고 초청하는 글을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 주제는 「우리 동네 반려동물 축제」, 프로그램은 나의 반려동물 소개하기와 반려동물 예절 배우기, 장소는 학교 운동장이에요. 반려동물과 함께 사는 이웃을 이해하는 즐거운 축제에 여러분을 초대합니다. 다음 주 토요일, 학교 운동장에서 함께해요.","scoring_points":["주제·프로그램·장소를 정했는가","초청하는 글을 두 문장으로 썼는가","다양한 문화의 이해·존중이 드러났는가"]},"explanation":["주제를 정해요.","프로그램과 장소예요.","초청 글을 써요."],"asset":{"type":"passage","lines":["하늘반은 「세계 문화 나눔 축제」를 계획했다.","프로그램 — 여러 나라 인사말 배우기, 세계 음식 그림 그리기","장소 — 학교 강당 · 우리 반이 초청하는 글을 써서 나눠 준다."],"title":"신문 ⑧ — 하늘반 축제 계획"}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO3-2-u2-C1','soc',3,2,'u2',1,'풍습과 세시 풍속 — 풍습은 옛날부터 되풀이되어 전해 오는 생활 습관과 생활 모습(생일 미역국, 돌잔치, 전통 결혼식, 김장) · 세시 풍속은 해마다 일정한 때에 되풀이하는 풍습(차례, 세시 음식, 전통 놀이) · 세시 풍속도 풍습의 하나 · 명절은 설날·정월 대보름·단오·추석처럼 해마다 일정하게 지켜 즐기는 날, 차례는 명절날 아침 조상들에게 지내는 제사, 덕담은 남이 잘되기를 바라며 나누는 좋은 말, 설빔은 설을 맞이해 새로 마련한 옷이나 신발',ARRAY['[4사04-01] 옛날과 오늘날의 풍습과 세시 풍속을 비교하고, 그 속에 담긴 생활 모습과 생각을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],1),
('SO3-2-u2-C2','soc',3,2,'u2',2,'옛날의 일상생활 속 풍습 — 두레는 한꺼번에 많은 일손이 필요한 농사일을 함께하려고 마을에 만든 공동 조직, 품앗이는 김장·지붕 얹기처럼 일손이 모자란 일을 서로 돌아가며 돕는 풍습(오늘날 육아·반찬 품앗이) · 일생 동안의 풍습: 출생(대문에 21일 동안 금줄) → 백일 → 첫돌(돌잡이: 쌀·붓·활·돈·실) → 관례(결혼 전 성인식) → 혼례 → 회갑(환갑, 60년 건강하게 사신 것 축하) → 장례 · 서로 축하하거나 위로하며 마음을 나눔',ARRAY['[4사04-01] 옛날과 오늘날의 풍습과 세시 풍속을 비교하고, 그 속에 담긴 생활 모습과 생각을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],2),
('SO3-2-u2-C3','soc',3,2,'u2',3,'옛날과 오늘날의 일상생활 속 풍습 비교 — 결혼 풍습: 옛날 신부 집·혼례복(한복)·나무 기러기(평생 함께)·폐백(신부가 신랑 쪽 어른께 큰절, 대추와 밤)·신부 집에서 며칠 뒤 신랑 집 / 오늘날 결혼식장·공원, 턱시도·웨딩드레스, 반지, 신혼여행 · 변함없는 것: 부부가 된 것을 알리고 가족과 친척이 미래를 축복하는 마음 · 변화하며 이어지는 풍습(백일잔치·회갑잔치·폐백), 사라져 가는 풍습(금줄 치기·관례), 장례는 매장이 줄고 수목장·해양장이 늘어남',ARRAY['[4사04-01] 옛날과 오늘날의 풍습과 세시 풍속을 비교하고, 그 속에 담긴 생활 모습과 생각을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],3),
('SO3-2-u2-C4','soc',3,2,'u2',4,'옛날의 세시 풍속 — 설날(음력 1월 1일, 설빔·세배·덕담·떡국, 윷놀이·널뛰기·연날리기) · 정월 대보름(음력 1월 15일, 달맞이·쥐불놀이·다리밟기, 부럼·오곡밥과 나물) · 단오(음력 5월 5일, 씨름·그네뛰기·부채, 수리취떡·앵두화채, 창포 삶은 물에 머리 감기) · 추석(음력 8월 15일, 차례·성묘·강강술래·소싸움, 송편) · 동지(양력 12월 22일 무렵, 밤이 가장 긴 날·작은 설, 팥죽·달력·버선) · 떡국 흰색은 밝은 한 해, 긴 모양은 건강하고 오래 살기 · 송편은 점점 나아지기를 바라는 마음 · 차례·윷놀이·떡국·송편·팥죽은 오늘날까지 이어짐',ARRAY['[4사04-01] 옛날과 오늘날의 풍습과 세시 풍속을 비교하고, 그 속에 담긴 생활 모습과 생각을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],4),
('SO3-2-u2-C5','soc',3,2,'u2',5,'옛날과 오늘날의 세시 풍속 비교 — 옛날 조상들은 주로 농사를 지었고 농사는 계절과 날씨의 영향을 받아 농사와 관련 있는 세시 풍속이 계절마다 다양했음(겨울 새해 첫 보름달에 풍년 기원, 가을 수확의 기쁨) · 오늘날에는 직업이 다양해져 농사짓는 사람이 줄어 큰 명절을 중심으로 한 세시 풍속이 이어짐 · 오늘날 설날: 차례·세배·떡국은 이어지는 모습, 여행·영화·케이크는 달라진 모습 · 가족이나 이웃과 기쁨을 함께 나누는 것은 변함없음',ARRAY['[4사04-01] 옛날과 오늘날의 풍습과 세시 풍속을 비교하고, 그 속에 담긴 생활 모습과 생각을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],5),
('SO3-2-u2-C6','soc',3,2,'u2',6,'옛날부터 전해 내려오는 풍습 체험 — 복주머니는 복이 들어온다는 뜻으로 설날 아침 옷에 차고 다녔고 오늘날에도 선물함 · 만드는 차례: 활동 자료 뜯기 → 색칠하고 모양대로 뜯기 → 풀로 모양 만들기 → 리본이나 끈으로 손잡이 · 전통 놀이: 윷놀이(윷·윷판·윷말, 도·개·걸·윷·모, 윷이나 모가 나오거나 상대 말을 잡으면 한 번 더), 제기차기, 투호(병에 화살), 고누(고누판에서 말 따기·가두기) · 안전과 규칙 · 전통 놀이 지도사',ARRAY['[4사04-01] 옛날과 오늘날의 풍습과 세시 풍속을 비교하고, 그 속에 담긴 생활 모습과 생각을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],6),
('SO3-2-u2-C7','soc',3,2,'u2',7,'옛날과 오늘날의 풍습 정리 — 세시 음식(떡국·송편·팥죽·오곡밥·수리취떡)과 명절·절기에 하던 일(쥐불놀이·다리밟기·강강술래·그네뛰기·부채 선물) · 오늘날 풍습에 담긴 뜻: 시험 보는 사람에게 엿(합격 기원), 어버이날 카네이션(부모님 사랑에 감사), 설날 복주머니(복이 들어오기를) · 전통 놀이에 새 도구를 더해 새 놀이 만들기(플라잉 디스크 윷놀이, 달리는 제기차기) · 풍습에는 생활과 생각이 담겨 있고 이어져 내려오는 풍습도 있음',ARRAY['[4사04-01] 옛날과 오늘날의 풍습과 세시 풍속을 비교하고, 그 속에 담긴 생활 모습과 생각을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],7),
('SO3-2-u2-C8','soc',3,2,'u2',8,'교통의 뜻 — 교통은 어떤 장소에서 다른 장소로 사람이 이동하거나 물건을 옮기는 것 · 교통수단은 이동하거나 물건을 옮길 때 사용하는 도구, 교통로는 교통에 이용하는 길 · 도로(버스·오토바이), 고속 국도(고속버스), 철도(열차·지하철), 자전거 도로, 수로(배·유람선), 눈에 보이지 않는 항공로(비행기) · 필요에 따라 다양하게 이용: 많은 짐(지게차·트럭), 위험에 빠진 사람 구조(구조 헬기), 높은 곳(케이블카)',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],8),
('SO3-2-u2-C9','soc',3,2,'u2',9,'옛날의 교통수단 — 옛날 사람들은 주로 걸어서 이동, 많이 다녀 생긴 길과 강을 교통로로 이용 · 말(먼 거리·빨리), 달구지(소나 말이 끄는 수레, 무거운 짐), 가마(가마꾼이 들어 옮김), 뗏목(통나무를 이어 긴 막대기로 밈), 나룻배(노를 저어 강 양쪽을 오감), 돛단배(바람의 힘을 이용하는 돛) · 자연에서 쉽게 얻는 재료, 사람·동물·바람(자연)의 힘 · 과학 기술의 발달로 기계의 힘: 증기 기차·증기선(수증기), 자동차·비행기(석유)',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],9),
('SO3-2-u2-C10','soc',3,2,'u2',10,'오늘날의 교통수단과 교통 시설 — 버스·트럭·자가용·오토바이·지하철·기차·자전거·킥보드, 하늘의 비행기·헬리콥터, 바다의 여객선·화물선·잠수함·요트 · 대부분 석유·가스·전기를 연료로 씀 · 교통 시설: 주유소, 기차역, 휴게소, 자동차 정비소, 버스 터미널, 활주로, 관제탑, 등대, 크레인 · 안전을 위한 신호와 약속(빨간색 등대는 왼쪽에 장애물이 있으니 오른쪽, 흰색 등대는 오른쪽에 장애물이 있으니 왼쪽) · 나라마다 자연환경과 생활에 따라 독특한 교통수단(공중에 매달린 전동차, 세 발 택시, 물길의 배)',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],10),
('SO3-2-u2-C11','soc',3,2,'u2',11,'교통의 변화로 달라진 생활 — 먼 곳까지 더 빠르고 편하게, 가기 어려웠던 곳에 쉽게 · 옛날 선비는 걸어서·말·나룻배로 15일 정도, 오늘날 어린이는 지하철·고속 열차·버스로 반나절 정도 · 달구지 → 트럭: 더 많은 짐을 먼 곳까지 · 생활 공간이 넓어짐(먼 직장·학교, 여러 곳의 물건, 먼 곳 여행) · 가마꾼·뱃사공은 거의 사라지고 철도 기관사·항공기 조종사·해양 경찰관·도선사(배가 안전하게 항구를 드나들도록 안내) 등이 새로 생김 · 교통 약자 택시',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],11),
('SO3-2-u2-C12','soc',3,2,'u2',12,'교통이 변화하며 생긴 문제와 해결 노력 — 문제: 교통 체증(차가 너무 많이 모여 길이 막힘), 교통사고, 대기 오염과 소음, 주차할 곳 부족 · 노력: 과학적인 교통 관리(막히는 길·사고 정보를 빠르게 알림), 새로운 교통 시설 개발, 친환경 에너지 사용, 새 주차 시설, 대중교통 중심, 전기 자전거 공유 · 교통안전 수칙: 횡단보도에서 주위 살피기, 무단 횡단 안 하기, 스마트폰 보며 걷지 않기, 자전거·킥보드는 정해진 도로에서 안전 장비, 어린이 보호 구역에서 자동차는 천천히',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],12),
('SO3-2-u2-C13','soc',3,2,'u2',13,'미래의 교통과 달라질 생활 — 자율 주행 휠체어(장애인·환자의 안전한 이동), 착용하는 로봇(무거운 물건), 우주선(우주여행·우주로 물건), 자율 주행 자동차(직접 운전할 필요 없음, 일하고 쉬는 공간), 자율 운항 선박(스스로 목적지까지), 초고속 자기 부상 열차(전기의 힘으로 떠서 터널을 통해 비행기보다 빠르게) · 도심 항공 교통(하늘로 다녀 교통 혼잡이 없고 공해·소음이 적음) · 더 빠르고 안전하면서 환경을 보호하는 방향 · 새 직업: 우주 관광 가이드, 도심 항공 관제사, 이착륙장 관리자, 인공지능 개발자',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],13),
('SO3-2-u2-C14','soc',3,2,'u2',14,'교통의 변화로 달라진 생활 정리 — 교통의 발달로 사람과 물건의 이동이 빨라지고 편리해짐 · 교통 체증·환경 문제 같은 문제도 생겨 지금도 해결하려고 노력 · 새 시설이 생기고 생활 모습이 달라짐 · 옛날 사람이 상상한 미래 교통수단(나는 신발) · 여러 나라의 독특한 교통 표지판(동물 조심, 걸으며 스마트폰 쓰지 말기, 보행자 우선 도로)',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],14),
('SO3-2-u2-C15','soc',3,2,'u2',15,'통신과 통신수단 — 통신은 소식이나 정보를 주고받는 것, 통신수단은 그때 사용하는 방법이나 도구(전화·텔레비전·컴퓨터·스마트폰·편지·전자 우편·인터폰) · 목적: 위험을 알리고 도움 청하기, 친구와 연락, 일기 예보로 날씨 알기, 길 도우미로 길 찾기 · 통신수단이 없다면 급한 소식을 직접 가서 전해야 하고 다른 지역 소식을 알기 어려움',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],15),
('SO3-2-u2-C16','soc',3,2,'u2',16,'옛날의 통신수단 — 서찰(안부·소식을 글로 적어 사람이 직접 전달), 방(나라의 중요한 소식을 사람들이 많이 모이는 곳에 붙임), 봉수(낮에는 연기·밤에는 불, 평상시 1개·적이 나타나면 2개·가까이 오면 3개·쳐들어오면 4개·싸움이 시작되면 5개), 파발(나라의 중요한 문서를 말을 타거나 걸어가 전달), 신호 연(암호를 적은 연), 신호 깃발, 북, 나발 · 특징: 시간이 오래 걸림, 많은 내용을 자세하고 정확하게 전하기 어려움, 날씨의 영향(안개가 짙으면 봉수가 안 보임)',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],16),
('SO3-2-u2-C17','soc',3,2,'u2',17,'오늘날의 통신수단 — 모바일 메신저(어디에서나 대화), 디지털 안내판(버스 오는 시각), 대기 정보 알리미(미세 먼지), 등하교 알리미, 무전기(구급 대원이 구조 헬기 요청), 텔레비전 뉴스·전자 우편, 길 도우미(내비게이션) · 학교: 전자 칠판, 태블릿 컴퓨터, 스피커(종소리·안내 방송), 전화기 · 하는 일에 따라: 야구 심판 수신호, 교통경찰 수신호와 호루라기, 축구 심판 색 카드, 마을 안내 방송 · 여러 사람과 동시에 많은 정보를 실시간으로 빠르게',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],17),
('SO3-2-u2-C18','soc',3,2,'u2',18,'통신수단의 변화로 달라진 생활 — 언제 어디서나 정보를 쉽고 빠르게, 직접 가지 않아도 할 수 있는 일이 많아짐(모바일 메신저, 집에서 물건 사기·은행 거래, 진료, 화상 회의) · 전화기: 초기의 전화기(벽, 숫자 번호판 없음, 교환원이 연결) → 유선 전화(숫자 번호판, 전화기 있는 곳으로 가야 함, 공중전화는 동전·전화 카드) → 휴대 전화(들고 다니며 통화) → 오늘날 휴대 전화(사진·쇼핑·은행) · 새 시설·직업: 기지국과 통신 설비 기술자, 인공위성 개발자, 촬영 기사, 폐회로 텔레비전 통합 관제 요원 · 사라진 것: 교환원, 무선 호출기 · 디지털 배움터, 변화를 따라가기 힘든 사람 배려',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],18),
('SO3-2-u2-C19','soc',3,2,'u2',19,'통신수단을 올바르게 이용하기 — 올바르게 쓰지 않으면 몸과 마음의 건강을 해치고 다른 사람에게 피해 · 이어폰 끼고 동영상 보며 걷기(위험), 공공장소에서 큰 소리 통화, 상처 주는 댓글, 허락 없이 사진 찍기, 나쁜 자세로 오래 게임 · 스마트폰 과의존은 일상생활에 문제가 생길 정도로 지나치게 쓰는 것 · 약속: 진동으로 바꾸고 작은 소리로 짧게, 바른 표현·확인되지 않은 정보 올리지 않기, 개인 정보 보안, 정한 시간에만, 때와 장소에 맞게, 길에서는 안전 · 통신 예절',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],19),
('SO3-2-u2-C20','soc',3,2,'u2',20,'통신수단의 변화로 달라진 생활 정리 — 옛날 통신수단(서찰·방·파발·봉수)은 자세한 정보를 전하기 어렵고 시간이 오래 걸림 · 오늘날에는 한 번에 많은 정보를 실시간으로, 하나의 통신수단으로 여러 통신 방법 · 새로운 시설과 직업 · 몸과 마음의 건강을 위해 안전하고 올바르게 사용 · 미래 통신수단 상상(불편했던 경험에서 출발) · 이모티콘 만들기(상황에 알맞은 말 → 모습 정하기 → 스케치·색칠)',ARRAY['[4사04-02] 교통수단과 통신수단의 변화로 달라진 사람들의 생활 모습을 탐구한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],20)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO3-2-u2-X01','soc',3,'u2',ARRAY['SO3-2-u2-C1']::text[],'풍습과 세시 풍속의 관계를 거꾸로 안다(세시 풍속은 풍습이 아니라고, 또는 풍습은 모두 세시 풍속이라고 여기는 등)','세시 풍속도 풍습이에요'),
('SO3-2-u2-X02','soc',3,'u2',ARRAY['SO3-2-u2-C1','SO3-2-u2-C3','SO3-2-u2-C7']::text[],'풍습은 옛날에만 있고 오늘날에는 볼 수 없다고 여긴다','오늘날에도 이어져요'),
('SO3-2-u2-X03','soc',3,'u2',ARRAY['SO3-2-u2-C1','SO3-2-u2-C4']::text[],'명절·차례·덕담·설빔 같은 낱말의 뜻을 서로 바꾸어 안다','낱말 뜻을 다시 봐요'),
('SO3-2-u2-X04','soc',3,'u2',ARRAY['SO3-2-u2-C2']::text[],'두레와 품앗이를 바꾸어 알거나, 옛날 사람들이 함께 일한 까닭을 잘못 안다','마을 조직 · 돌아가며 돕기'),
('SO3-2-u2-X05','soc',3,'u2',ARRAY['SO3-2-u2-C2']::text[],'일생 동안의 풍습(금줄·돌잔치·관례·혼례·회갑·장례)의 차례나 뜻을 바꾸어 안다','태어나서 늙기까지 차례대로'),
('SO3-2-u2-X06','soc',3,'u2',ARRAY['SO3-2-u2-C2']::text[],'옛날 풍습에 담긴 마음(축하·위로·서로 돕는 정)을 놓친다','기쁨과 슬픔을 함께 나눠요'),
('SO3-2-u2-X07','soc',3,'u2',ARRAY['SO3-2-u2-C3']::text[],'옛날과 오늘날의 결혼 풍습(장소·옷·주고받는 물건·마친 뒤)을 바꾸어 안다','나무 기러기 · 반지'),
